@startuml

class Airline {
  + ID
}

class Flight {
  + ID
  + departure_time
  + arrival_time
}

class Airport {
  + ID
}

class Aircraft {
  + state
}

class Pilot {
  + experience_level
}

class AeroplaneType {
}

Airline "1" -- "*" Flight : operates
Airline "1" -- "*" Aircraft : owns

Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives to
Flight "*" -- "1" Aircraft : uses

Flight "1" -- "1" Pilot : captain
Flight "1" -- "1" Pilot : co-pilot

AeroplaneType "1" -- "*" Aircraft : is type of
AeroplaneType "1" -- "*" Pilot : requires

@enduml

